const names = ALL_TOOLS.map(x => x.name).filter(n =>
  n.startsWith("mcp__linear__") ||
  n.startsWith("mcp__github__") ||
  n.startsWith("mcp__codex_apps__linear_") ||
  n.startsWith("mcp__codex_apps__github_") ||
  n.startsWith("mcp__codex_apps__slack_") ||
  n.startsWith("mcp__entire__") ||
  n.startsWith("mcp__ultrabrain__")
);
text(names.join("\n"));

const wanted = [
  "mcp__github__get_me",
  "mcp__linear__whoami",
  "mcp__linear__get_issue",
  "mcp__codex_apps__slack_slack_list_workspaces",
  "mcp__codex_apps__slack_slack_read_channel"
];
for (const name of wanted) {
  const item = ALL_TOOLS.find(x => x.name === name);
  text(`===${name}===\n${item ? item.description : "NOT_FOUND"}`);
}

