$errors = [System.Collections.Generic.List[object]]::new()
$hookRecords = [System.Collections.Generic.List[object]]::new()

$hookScopes = [System.Collections.Generic.List[object]]::new()
$hookScopes.Add([pscustomobject]@{
    scope = 'organization'
    owner = $org
    repo = $null
    endpoint = "/orgs/$org/hooks?per_page=100"
})
foreach ($repo in $repos) {
    $hookScopes.Add([pscustomobject]@{
        scope = 'repository'
        owner = $org
        repo = $repo.name
        endpoint = "/repos/$org/$($repo.name)/hooks?per_page=100"
    })
}

foreach ($scope in $hookScopes) {
    try {
        $hookPages = Invoke-GhJson -Endpoint $scope.endpoint -Paginate
        $hooks = @(ConvertTo-FlatArray -Value $hookPages)
    }
    catch {
        $errors.Add([pscustomobject]@{
            surface = 'hooks'
            scope = $scope.scope
            owner = $scope.owner
            repo = $scope.repo
            error = $_.Exception.Message
        })
        continue
    }

    foreach ($hook in $hooks) {
        $deliveryEndpoint = if ($scope.scope -eq 'organization') {
            "/orgs/$org/hooks/$($hook.id)/deliveries?per_page=100"
        }
        else {
            "/repos/$org/$($scope.repo)/hooks/$($hook.id)/deliveries?per_page=100"
        }

        try {
            $deliveryPages = Invoke-GhJson -Endpoint $deliveryEndpoint -Paginate
            $deliveries = @(ConvertTo-FlatArray -Value $deliveryPages | Where-Object {
                $deliveredAt = [DateTimeOffset]::Parse($_.delivered_at)
                $deliveredAt -ge $windowStart -and $deliveredAt -le $windowEnd
            })
            $deliveryError = $null
        }
        catch {
            $deliveries = @()
            $deliveryError = $_.Exception.Message
            $errors.Add([pscustomobject]@{
                surface = 'hook_deliveries'
                scope = $scope.scope
                owner = $scope.owner
                repo = $scope.repo
                hookId = $hook.id
                error = $deliveryError
            })
        }

        $hookRecords.Add([pscustomobject]@{
            scope = $scope.scope
            owner = $scope.owner
            repo = $scope.repo
            id = $hook.id
            type = $hook.type
            name = $hook.name
            active = $hook.active
            events = @($hook.events)
            contentType = $hook.config.content_type
            insecureSsl = $hook.config.insecure_ssl
            url = $hook.config.url
            updatedAt = $hook.updated_at
            deliveries = @($deliveries | ForEach-Object {
                [pscustomobject]@{
                    id = $_.id
                    guid = $_.guid
                    event = $_.event
                    action = $_.action
                    deliveredAt = $_.delivered_at
                    redelivery = $_.redelivery
                    statusCode = $_.status_code
                    duration = $_.duration
                }
            })
            deliveryError = $deliveryError
        })
    }
}

$result = [pscustomobject]@{
    observedAt = [DateTimeOffset]::UtcNow.ToString('o')
    apiVersion = $apiVersion
    window = [pscustomobject]@{
        start = $windowStart.ToString('o')
        end = $windowEnd.ToString('o')
    }
    activeRepositories = @($repos | ForEach-Object {
        [pscustomobject]@{
            id = $_.id
            nodeId = $_.node_id
            name = $_.name
            visibility = $_.visibility
            defaultBranch = $_.default_branch
            url = $_.html_url
        }
    })
    installations = @($installations.installations | ForEach-Object {
        [pscustomobject]@{
            id = $_.id
            appId = $_.app_id
            appSlug = $_.app_slug
            targetType = $_.target_type
            targetId = $_.target_id
            repositorySelection = $_.repository_selection
            permissions = $_.permissions
            events = $_.events
            suspendedAt = $_.suspended_at
            createdAt = $_.created_at
            updatedAt = $_.updated_at
        }
    })
    hooks = $hookRecords.ToArray()
    errors = $errors.ToArray()
}

$json = $result | ConvertTo-Json -Depth 100
[System.IO.File]::WriteAllText($outputPath, $json, [System.Text.UTF8Encoding]::new($false))
$hash = (Get-FileHash -LiteralPath $outputPath -Algorithm SHA256).Hash.ToLowerInvariant()

[pscustomobject]@{
    output = $outputPath
    sha256 = $hash
    activeRepositories = $result.activeRepositories.Count
    installations = $result.installations.Count
    hooks = $result.hooks.Count
    deliveriesInWindow = @($result.hooks.deliveries).Count
    errors = $result.errors.Count
} | ConvertTo-Json -Compress

