async function allComments(issueId) {
  let cursor; const out=[]; let pages=0;
  do {
    const r = await tools.mcp__linear__list_comments({issueId, limit: 100, orderBy:"createdAt", ...(cursor?{cursor}:{})});
    if (r?.isError) throw new Error(JSON.stringify(r));
    const data = JSON.parse(r.content?.find(x=>x.type==="text")?.text || "{}");
    const batch = data.comments || data.items || data.nodes || (Array.isArray(data)?data:[]);
    out.push(...batch); pages++;
    const pi=data.pageInfo||{};
    cursor=pi.hasNextPage?(pi.endCursor||pi.nextCursor):undefined;
    if(pages>50) throw new Error("comments_pagination_guard");
  } while(cursor);
  return {pages,items:out};
}
async function allUpdates() {
  let cursor; const out=[]; let pages=0;
  do {
    const r=await tools.mcp__linear__get_status_updates({
      type:"project",
      project:"5ac60fe1-ea78-42ed-84f9-378eef9226a9",
      createdAt:"2026-10-31T00:00:00Z",
      includeArchived:true,
      limit:100,
      orderBy:"createdAt",
      ...(cursor?{cursor}:{})
    });
    if(r?.isError) throw new Error(JSON.stringify(r));
    const data=JSON.parse(r.content?.find(x=>x.type==="text")?.text||"{}");
    const batch=data.statusUpdates||data.items||data.nodes||(Array.isArray(data)?data:[]);
    out.push(...batch); pages++;
    const pi=data.pageInfo||{};
    cursor=pi.hasNextPage?(pi.endCursor||pi.nextCursor):undefined;
    if(pages>50) throw new Error("updates_pagination_guard");
  } while(cursor);
  return {pages,items:out};
}
