const results = await Promise.all([
  tools.mcp__github__projects_get({method:"get_project",owner:"LCV-Ideas-Software",owner_type:"org",project_number:15}),
  tools.mcp__github__projects_get({method:"get_project",owner:"LCV-Ideas-Software",owner_type:"org",project_number:17})
]);
for (const [i,r] of results.entries()) {
  text(`PROJECT_${i===0?15:17}`);
  for (const c of (r?.content ?? [])) if (c.type === "text") text(c.text);
}

const r = await tools.mcp__github__projects_list({
  method:"list_project_items",
  owner:"LCV-Ideas-Software",
  owner_type:"org",
  project_number:15,
  perPage:50
});
const t=(r?.content??[]).find(c=>c.type==="text")?.text ?? "";
const j=JSON.parse(t);
text(JSON.stringify({pageInfo:j.pageInfo,itemCount:j.items?.length,keys:Object.keys(j),first:j.items?.[0]}));

let after=undefined, pages=0, items=[];
do {
  const args={method:"list_project_items",owner:"LCV-Ideas-Software",owner_type:"org",project_number:15,perPage:50};
  if(after) args.after=after;
  const r=await tools.mcp__github__projects_list(args);
  const t=(r?.content??[]).find(c=>c.type==="text")?.text;
  if(!t) throw new Error("Resposta sem JSON");
  const j=JSON.parse(t);
  items.push(...(j.items??[]));
  pages++;
  after=j.pageInfo?.hasNextPage ? j.pageInfo.nextCursor : undefined;
} while(after);
const byType={}; const byRepo={}; const cross=[];
for(const it of items){
  byType[it.content_type]=(byType[it.content_type]??0)+1;
  const repo=it.content?.repository??"(draft)";
  byRepo[repo]=(byRepo[repo]??0)+1;
  if(repo!=="LCV-Ideas-Software/github-operations" && repo!=="(draft)") cross.push({id:it.node_id,type:it.content_type,repo,number:it.content?.number,created_at:it.created_at,updated_at:it.updated_at,url:it.content?.html_url});
}
cross.sort((a,b)=>String(a.created_at).localeCompare(String(b.created_at)));
text(JSON.stringify({pages,total:items.length,byType,repoCount:Object.keys(byRepo).length,byRepo,crossCount:cross.length,crossLatest:cross.slice(-10)},null,2));

const r=await tools.mcp__github__projects_list({method:"list_projects",owner:"LCV-Ideas-Software",owner_type:"org",perPage:50});
const t=(r?.content??[]).find(c=>c.type==="text")?.text;
const j=JSON.parse(t);
const projects=(j.projects??[]).map(p=>({number:p.number,title:p.title,closed_at:p.closed_at,updated_at:p.updated_at,node_id:p.node_id})).sort((a,b)=>a.number-b.number);
text(JSON.stringify({pageInfo:j.pageInfo,total:projects.length,projects},null,2));

