        [object]$Node,

        [Parameter(Mandatory)]
        [System.Collections.Generic.List[object]]$Results
    )

    if ($Node.type -eq 'paragraph') {
        $Results.Add($Node)
    }

    if ($Node.PSObject.Properties['content'] -and $null -ne $Node.content) {
        foreach ($child in @($Node.content)) {
            Get-ParagraphNodes -Node $child -Results $Results
        }
    }
}

function Get-NodeText {
    param(
        [Parameter(Mandatory)]
        [object]$Node
    )

    $nodes = [System.Collections.Generic.List[object]]::new()
    Get-TextNodes -Node $Node -Results $nodes
    return [string]::Concat(@($nodes | ForEach-Object { $_.text }))
}

function Replace-UniqueTextFragment {
    param(
        [Parameter(Mandatory)]
        [System.Collections.Generic.List[object]]$TextNodes,

        [Parameter(Mandatory)]
        [string]$Old,

        [Parameter(Mandatory)]
        [AllowEmptyString()]
        [string]$New
    )

    $matches = @($TextNodes | Where-Object { $_.text.Contains($Old, [StringComparison]::Ordinal) })
    if ($matches.Count -ne 1) {
        throw "Expected exactly one rich-text node containing '$Old', observed $($matches.Count)."
    }

    $node = $matches[0]
    $first = $node.text.IndexOf($Old, [StringComparison]::Ordinal)
    $second = $node.text.IndexOf($Old, $first + $Old.Length, [StringComparison]::Ordinal)
    if ($second -ge 0) {
        throw "Expected one occurrence of '$Old' in its rich-text node."
    }
    $node.text = $node.text.Substring(0, $first) + $New + $node.text.Substring($first + $Old.Length)
}

function Replace-UniqueParagraphSpan {
    param(
        [Parameter(Mandatory)]
        [System.Collections.Generic.List[object]]$Paragraphs,

        [Parameter(Mandatory)]
        [string]$Start,

        [Parameter(Mandatory)]
        [string]$End,

        [Parameter(Mandatory)]
        [string]$New
    )

    $matches = @($Paragraphs | Where-Object {
        $text = Get-NodeText -Node $_
        $text.Contains($Start, [StringComparison]::Ordinal) -and $text.Contains($End, [StringComparison]::Ordinal)
    })
    if ($matches.Count -ne 1) {
        throw "Expected exactly one paragraph spanning '$Start' through '$End', observed $($matches.Count)."
    }

    $paragraph = $matches[0]
    $content = @($paragraph.content)
    $startNodeIndex = -1
    $startTextIndex = -1
    $endNodeIndex = -1
    $endTextIndex = -1

    for ($index = 0; $index -lt $content.Count; $index++) {
        if (-not $content[$index].PSObject.Properties['text']) {
            continue
        }
        if ($startNodeIndex -lt 0) {
            $candidate = $content[$index].text.IndexOf($Start, [StringComparison]::Ordinal)
            if ($candidate -ge 0) {
                $startNodeIndex = $index
                $startTextIndex = $candidate
            }
        }
        if ($startNodeIndex -ge 0) {
            $candidate = $content[$index].text.IndexOf($End, [StringComparison]::Ordinal)
            if ($candidate -ge 0) {
                $endNodeIndex = $index
                $endTextIndex = $candidate
                break
            }
        }
    }

    if ($startNodeIndex -lt 0 -or $endNodeIndex -lt $startNodeIndex) {
        throw 'Unable to locate the unique rich-text span boundaries.'
    }

    $newContent = [System.Collections.Generic.List[object]]::new()
    for ($index = 0; $index -lt $startNodeIndex; $index++) {
        $newContent.Add($content[$index])
    }

    $prefix = $content[$startNodeIndex].text.Substring(0, $startTextIndex)
    if ($prefix.Length -gt 0) {
        $content[$startNodeIndex].text = $prefix
        $newContent.Add($content[$startNodeIndex])
    }

    $newContent.Add([pscustomobject]@{
        type = 'text'
        text = $New
    })

    $suffixStart = $endTextIndex + $End.Length
    $suffix = $content[$endNodeIndex].text.Substring($suffixStart)
    if ($suffix.Length -gt 0) {
        $content[$endNodeIndex].text = $suffix
        $newContent.Add($content[$endNodeIndex])
    }

    for ($index = $endNodeIndex + 1; $index -lt $content.Count; $index++) {
        $newContent.Add($content[$index])
    }
    $paragraph.content = @($newContent)
}

$templateQuery = @'
query RecurringTemplateBeforeUpdate($id: String!) {
  template(id: $id) {
    id
    name
    description
    type
    updatedAt
