Replace-UniqueParagraphSpan -Paragraphs $paragraphs -Start 'Across all repositories declaring Wrangler (' -End 'sponsor-motor)' -New 'Across every live repository and workspace that declares Wrangler, discovered from current manifests and lockfiles'

$citationMarkers = @('[cite: 1]', '[cite: 3]', '[cite: 1, 2]', '[cite: 1, 3]', '[cite: 1, 2, 3]')
$citationCountBefore = 0
foreach ($node in $textNodes) {
